                }

                let should_defer_header = matches!(phase, super::RemoteStartupPhase::Connecting)
                    && elapsed < REMOTE_STARTUP_HEADER_DEBOUNCE;

                if should_defer_header {
                    None
                } else {
                    Some(phase.header_label_with_elapsed(elapsed))
                }
            })

